513: 	if repoID == "" {
514: 		repoID, err = gitops.GenerateRepoID(entry.RootPath)
515: 		if err != nil {
516: 			return nil, fmt.Errorf("generating repo ID: %w", err)
517: 		}
518: 	}
519: 	repoRoot := entry.RootPath
520: 
